import React, { useEffect, useState, Fragment } from 'react'
import { Routes, Route, Link } from "react-router-dom";
import axios from 'axios'
import Container from './components_universal/Container';
import Navbar from './Navbar';
import Label from './components_universal/Label'
import InputStyleForm from './components_universal/InputStyleForm';
import CardStyleForm from './components_universal/CardStyleForm';
import Form from './components_universal/Form';
import Button from './components_universal/Button';
import ImageStyleCustom from './components_universal/ImageStyleCustom';
import swal from 'sweetalert2'

function SignUp() {
    const [username, setUsername] = useState("");
    const [email, setEmail] = useState("");
    const [number, setNumber] = useState("");
    const [password, setPassword] = useState("");
    const [userList, setUserList] = useState([]);
    const [edit, setEdit] = useState(false);

    const submitHandler = async (e) => {
        e.preventDefault();
        if (
            username.trim() !== "" &&
            email.trim() !== "" &&
            number.trim() !== "" &&
            password.trim() !== ""
        ) {

            const formData = {
                username: username,
                email: email,
                number: number,
                password: password
            }

            const { data } = await axios.post('http://localhost:3001/register', formData);
            new swal({
                icon: "success",
                text: data.message,
            });
            resetForm();
        } else {
            new swal({
                icon: "error",
                text: "put necessary information",
            });
        }
    };


    function resetForm() {
        setUsername("");
        setEmail("");
        setNumber("");
        setPassword("");
    }

    return (
        <Fragment>
            <Container width="full" display="row" justify="around">
                <Navbar />
                <CardStyleForm>
                    <Form onSubmit={submitHandler}>
                        <Label htmlFor="username" label="Username" />
                        <InputStyleForm
                            onChange={(e) => setUsername(e.target.value)}
                            value={username}
                            id="username"
                            placeholder="Username"
                        />
                        <Label htmlFor="email" label="Email" />
                        <InputStyleForm
                            onChange={(e) => setEmail(e.target.value)}
                            value={email}
                            id="email"
                            placeholder="Email"
                        />
                        <Label htmlFor="number" label="Number" />
                        <InputStyleForm
                            onChange={(e) => setNumber(e.target.value)}
                            value={number}
                            id="number"
                            placeholder="Number"
                            type="number"
                        />
                        <Label htmlFor="password" label="Password" />
                        <InputStyleForm
                            onChange={(e) => setPassword(e.target.value)}
                            value={password}
                            id="password"
                            placeholder="Password"
                            type="password"
                        />
                        <Button val={"Register"} bg="green" />
                    </Form>
                    <div className='flex justify-center items-center my-3'>
                        <Link
                            className="navbar-item"
                            activeClassName="is-active"
                            to="/SignIn"
                            exact
                        >
                            Already have account? Sign in here!
                        </Link>
                    </div>
                </CardStyleForm>
                <ImageStyleCustom width="4/6" source={`https://www.k9ofmine.com/wp-content/uploads/2020/01/Dogs-for-Busy-Families-850x520.jpg`} alt="dogFamily" />
            </Container>

        </Fragment>
    )
}

export default SignUp