import React from 'react'
import Grid from './grid'
import ListItem from './components_universal/ListItem'
import Button from './components_universal/Button'
import Image from './components_universal/Image'
import axios from 'axios'
import react, { Fragment, useState, useEffect } from "react"
import Navbar from './Navbar'
import Emoji from 'a11y-react-emoji';
import Modal from './components_universal/Modal'

function LottaDogs(props) {

    //---------------------------------------------------------------------------------
    const [dogBreeds, setDogBreeds] = useState([]);
    const [modalOpen, setModalOpen] = useState(false);
    const [LottaDogData, setLottaDogData] = useState([]);
    useEffect(() => {
        async function getdogsFromApi() {
            const { data } = await axios.get('https://api.thedogapi.com/v1/breeds');
            setDogBreeds(data);
        }
        getdogsFromApi()
    }, [dogBreeds])

    const dogData = async (id) => {
        const { data } = await axios.get('https://api.thedogapi.com/v1/breeds');
        console.log(data)
        const findDogData = data.find((dog) => { return dog.id === id });
        setLottaDogData(findDogData)
        openModal()
    }

    function openModal() {
        setModalOpen(true)
    }
    function closePop() {
        setModalOpen(false)
    }
    //---------------------------------------------------------------------------------
    return (
        <Fragment>
            <Navbar />
            <div className='mt-20 mb-5 text-center font-bold text-3xl'>All the breeds for you <Emoji symbol="🐶" label="Dog" /></div>
            <div className='flex flex-row justify-around w-auto flex-wrap'>
                {
                    dogBreeds && dogBreeds.map(el => (
                        <ListItem ner={el.name} key={`dog--${el.id}`}>
                            <Image source={el.image.url} alt={el.name} />
                            <Button onClick={() => dogData(el.id)} bg="blue" val="Lotta..." />
                        </ListItem>
                    ))
                }
            </div>
            {
                modalOpen && <Modal close={closePop} info={LottaDogData} />
            }
        </Fragment>
    )
}

export default LottaDogs