import react, { useState, useEffect } from "react";
import Button from "./components_universal/Button"
import axios from 'axios';
import Body from "./Body";
import Grid from "./grid";
import Container from "./components_universal/Container";
import Navbar from "./Navbar";
import Footer from "./Footer";
import Modal from "./components_universal/Modal"
import { Link } from "react-router-dom";

function App() {

  const [dogBreedList, setDogBreedList] = useState([]);
  const [moreDogData, setMoreDogData] = useState([])
  const [dogImage, setDogImage] = useState([]);
  const [modalopen, setModalOpen] = useState(false)

  const dogData = async (id) => {
    const { data } = await axios.get('https://api.thedogapi.com/v1/breeds');
    console.log(data)
    const findDogData = data.find((dog) => {return dog.id === id});
    setMoreDogData(findDogData)
    openModal()
  }

  useEffect(() => {
    async function getdogsFromApi(){
      const { data } = await axios.get('https://api.thedogapi.com/v1/breeds');
      const fiveDogs = [];
      for(let i = 0; i < 10; i++){
        let dog = data[Math.floor(Math.random()*data.length)];
        fiveDogs.push(dog)
      }
      setDogBreedList(fiveDogs);
    }
    getdogsFromApi()
  }, [])

  function openModal (){
    setModalOpen(true)
  }
  function closePop () {
    setModalOpen(false)
    setMoreDogData([])
  }
  return (
    <react.Fragment>
        <Container width="full" height="screen" display="col" justify="start">
            <Navbar/>
            <Body/>
            <Container width="full" height="96" display="row" justify="around">
            <Grid data={dogBreedList} imageData={dogImage} moreData={dogData}/>
            </Container>
        </Container>
        {
        modalopen && <Modal close={closePop} info={moreDogData} />
        }
    </react.Fragment>
  );
}

export default App;
